    'Budapest is the capital and most populous city of Hungary. It is Hungary''s primate city with 1.7 million inhabitants and its greater metro area has a population of about 3.3 million, representing one-third of the country''s population and producing above 40% of the country''s economic output. Budapest is the political, economic, and cultural center of the country, among the ten largest cities in the European Union and the second largest urban area in Central and Eastern Europe. Budapest stands on the River Danube and is strategically located at the center of the Pannonian Basin, lying on ancient trade routes linking the hills of Transdanubia with the Great Plain.', 'Budapest is the capital and most populous city of Hungary. It is Hungary''s primate city with 1.7 million inhabitants and its greater metro area has a population of about 3.3 million, representing one-third of the country''s population and producing above 40% of the country''s economic output. Budapest is the political, economic, and cultural center of the country, among the ten largest cities in the European Union and the second largest urban area in Central and Eastern Europe. Budapest stands on the River Danube and is strategically located at the center of the Pannonian Basin, lying on ancient trade routes linking the hills of Transdanubia with the Great Plain.',
    'wikipedia', 'https://en.wikipedia.org/wiki/Budapest', 'CC BY-SA', 'Wikipedia contributors, Budapest', now()
  from country_ref
  on conflict (country_id, slug) do update set
    name_az = excluded.name_az,
    name_en = excluded.name_en,
    name_ru = excluded.name_ru,
    lat = excluded.lat,
    lng = excluded.lng,
    population = excluded.population,
    short_desc_en = excluded.short_desc_en,
    description_en = excluded.description_en,
    source = excluded.source,
    source_url = excluded.source_url,
    license = excluded.license,
    attribution_text = excluded.attribution_text,
    last_synced_at = now()
  returning id, country_id
